import requests, sys, uuid, time
BASE = '{{TESTVDB_DB_URL}}'
c = 'tc_snap_wait_null_' + uuid.uuid4().hex[:8]

# Setup: create a collection first
r = requests.put(f'{BASE}/collections/{c}', json={
    "vectors": {"size": 4, "distance": "Cosine"}
})
if r.status_code not in (200, 201):
    print(f'setup failed: {r.status_code}')
    sys.exit(0)
time.sleep(0.5)

# Test: wait=null on create_snapshot
r = requests.post(f'{BASE}/collections/{c}/snapshots', json={
    "wait": None
})
if r.status_code == 200:
    print(f'[DEFECT: ILLEGAL_SUCCESS] wait=null accepted on create_snapshot')
    sys.exit(1)
else:
    print(f'wait=null correctly rejected: {r.status_code} {r.text[:200]}')
    sys.exit(0)

